contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take two amounts: depositAmount to fund a deposit, and extraDeposit to optionally deposit again after withdraw.
    // The test will deposit depositAmount, call withdrawAll(), then deposit extraDeposit and read effects.
    function run(uint depositAmount, uint extraDeposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount) + (extraDeposit)); require(depositAmount <= 1000000000000000000000000000000); require(extraDeposit <= 1000000000000000000000000000000);
        // ensure this contract has enough Ether to perform deposits
        require(address(this).balance >= depositAmount + extraDeposit);

        // initial contract balance observed
        uint beforeC = address(c).balance;

        // perform initial deposit to create credit for this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // attempt withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // perform another deposit after withdraw attempt
        c.deposit{value: extraDeposit}(); if (__ESBMC_reverted()) return;

        // read contract balance after operations
        uint afterC = address(c).balance;

        // General invariant to assert for all inputs:
        // If withdrawAll did NOT revert, then the final contract balance is at least beforeC + extraDeposit
        // (meaning withdrawAll could only reduce contract balance by at most the earlier deposit we made, and it cannot create new credit or otherwise increase c's balance beyond deposits we made afterward).
        // If withdrawAll reverted, then final contract balance must equal beforeC + depositAmount + extraDeposit
        // (i.e., a revert means withdrawAll had no state-change effect, so c kept the deposited funds).
        assert(
            (!reverted && afterC >= beforeC + extraDeposit) ||
            (reverted && afterC == beforeC + depositAmount + extraDeposit)
        );
    }

    // accept Ether sent to this test contract so deposits can be funded
    receive() external payable {}
}

