// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount, uint256 extraDeposit) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        extraDeposit = bound(extraDeposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount + extraDeposit);
        uint beforeC = address(c).balance;
        try c.deposit{value: depositAmount}() {} catch { return; }
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        try c.deposit{value: extraDeposit}() {} catch { return; }
        uint afterC = address(c).balance;
        assertTrue((!reverted && afterC >= beforeC + extraDeposit) ||
            (reverted && afterC == beforeC + depositAmount + extraDeposit));
    }

    function testFuzz_run(uint256 depositAmount, uint256 extraDeposit) public {
        _run(depositAmount, extraDeposit);
    }

    receive() external payable {}
}
